<script setup>
import { ref, onMounted, computed } from 'vue';
import L from 'leaflet';
import { MarkerClusterGroup } from 'leaflet.markercluster/src';
import BaseFilters from './BaseFilters.vue';
import BaseTooltipCard from './BaseTooltipCard.vue';
import { calculateBounds } from '../utils/calculate-bounds';
import { calculateCenter } from '../utils/calculate-center';
import { makeMarkerIcon } from '../utils/make-marker-icon';
import { makeTooltipCard } from '../utils/make-tooltip-card';
import { makeFilterButtonHTML } from '../utils/make-filter-button-html';
import { makeListViewButtonHTML } from '../utils/make-list-view-button-html';
import { createMarkerHighlighter } from '../utils/selected-marker';
import { createPolygonSelector } from '../utils/selected-polygon';
import BaseSearchInput from './BaseSearchInput.vue';
import 'leaflet/dist/leaflet.css';
import 'leaflet.markercluster/dist/MarkerCluster.css';
import '../utils/map-window-api';
import { getColorFromMarker } from '../utils/get-color-from-marker';

const props = defineProps({
	datasets: {
		type: Array,
		default: () => [],
	},
	selectedDatasets: {
		type: Array,
		required: true
	},
	settings: {
		type: Array,
		default: () => [],
	},
	primaryColor: {
		type: String,
		required: true,
		default: '#328725',
	},
	tileLayerUri: {
		type: String,
		required: true,
	},
});

const tooltipCard = ref(null);
const showFiltersCard = ref(false);
const mapRef = ref(null);
// Reference to this instance's map DOM element, so multiple maps can coexist on one page.
const mapContainer = ref(null);
// Polygon selection state scoped to this map instance.
const { selectOverlappingPolygon, resetPolygonSelection } = createPolygonSelector();
// Marker highlight state scoped to this map instance.
const { highlightSelectedMarker, resetMarkers, activeMarkerRef } = createMarkerHighlighter();
const clusters = ref([]);
const searchQuery = ref('');
const resultsCount = ref(0);
const lastSearchMarker = ref(null);
const clusterOptions = {
  spiderfyOnMaxZoom: true,
  showCoverageOnHover: false,
  zoomToBoundsOnClick: true,
  maxClusterRadius: 40,
  disableClusteringAtZoom: 15,
  iconCreateFunction: (cluster) => {
    const count = cluster.getChildCount();
    return L.divIcon({
      html: `
        <div class="owc-openkaarten-streetmap__cluster-group">
          <div class="owc-openkaarten-streetmap__cluster-group__circle">
            <span class="owc-openkaarten-streetmap__cluster-group__count">${count}</span>
          </div>
        </div>
      `,
      className: '',
      iconSize: L.point(40, 40),
    });
  },
};

const closeTooltipCard = () => {
	tooltipCard.value = null;
  resetMarkers(mapContainer.value);
  resetPolygonSelection();
  mapContainer.value?.focus();
};

const closeFilters = () => {
	showFiltersCard.value = false;
};

const datasetChange = (id, checked) => {
	console.log('datasetChange called with:', id, checked);
	if (!id) return null;
	emit('datasetChange', id, checked);
	const map = mapRef.value;
	const layers = clusters.value;
	const datalayerCluster = layers.find(
		(layer) => layer.id === id
	)?.cluster;
	const existsOnMap = map.hasLayer(datalayerCluster);
	if (checked) {
		if (existsOnMap) return null;
		map.addLayer(datalayerCluster);
	} else {
		map.removeLayer(datalayerCluster);
	}
};

// Move attachEvents outside of initializeMap
const attachEvents = (marker, location, set) => {
  marker.on('click', (e) => {
    highlightSelectedMarker(marker, mapContainer.value);

    if (location.geometry?.type !== 'Polygon') {
      resetPolygonSelection();
      tooltipCard.value = makeTooltipCard(location, set);
      return;
    }

    // For polygons, select overlapping polygon and use its data for tooltip.
    const selectedLayer = selectOverlappingPolygon(mapRef.value, e.latlng, location.properties?.marker);

    // Use the selected layer's data for the tooltip if available.
    if (selectedLayer && selectedLayer._featureData && selectedLayer._datasetData) {
      tooltipCard.value = makeTooltipCard(selectedLayer._featureData, selectedLayer._datasetData);
    } else {
      // Fallback to original data if layer data not found.
      tooltipCard.value = makeTooltipCard(location, set);
    }
  });

  marker.on('keydown', ({ originalEvent }) => {
    if (originalEvent.key === 'Enter') {
      tooltipCard.value = makeTooltipCard(location, set);
      highlightSelectedMarker(marker, mapContainer.value);
    }
  });
};

/**
 * Build the correct Leaflet layer for a GeoJSON feature.
 *
 * Synchronous by design: marker icons are applied as lightweight placeholders immediately
 * and upgraded to the processed SVG in the background once `fetchAndProcessSvg` resolves.
 * This keeps map initialization off the critical path of the SVG network requests, so the
 * tile layer and all markers are visible right away instead of blocking on a potentially
 * slow `/opengemeenten-iconenset/` fetch.
 *
 * @author Merel Voorn - van Uffelen
 *
 * @param {object} feature  A single GeoJSON feature from the dataset.
 * @param {object} dataset  The parent dataset — retained for debug logging / future use.
 * @returns {object} A Leaflet layer ready to be added to a cluster / map.
 */
const createLayer = (feature, dataset) => {
  console.log('Creating layer for feature:', feature);
  if (feature.geometry.type === 'Polygon' || feature.geometry.type === 'MultiPolygon') {
    return new L.GeoJSON(feature, {
      style: () => {
        const color = getColorFromMarker(feature.properties?.marker, props.primaryColor);
        return {
          color: color,
          fillColor: color,
          fillOpacity: 0.2,
          weight: 2
        };
      }
    });
  }

  // Handle MultiPoint features.
  if (feature.geometry.type === 'MultiPoint') {
    const markers = L.featureGroup();
    for (const coord of feature.geometry.coordinates) {
      const latlng = L.latLng(coord[1], coord[0]);
      // Get the placeholder icon synchronously, then upgrade it per-marker when the SVG lands.
      const { icon, ready } = makeMarkerIcon(L, {
        marker: feature.properties?.marker,
        defaultColor: props.primaryColor,
      });
      const marker = new L.Marker(latlng, { icon });
      ready.then((upgradedIcon) => {
        if (upgradedIcon) {
          marker.setIcon(upgradedIcon);
        }
      });
      markers.addLayer(marker);
    };
    return markers;
  }

  // Handle regular points using GeoJSON.
  // All markers in this feature share one icon config, so we create one placeholder up front
  // and upgrade every generated marker at once when the SVG fetch resolves.
  const { icon, ready } = makeMarkerIcon(L, {
    marker: feature.properties?.marker,
    defaultColor: props.primaryColor,
  });

  const pendingMarkers = [];

  const layer = new L.GeoJSON(feature, {
    pointToLayer: (feature, latlng) => {
      const marker = new L.Marker(latlng, { icon });
      pendingMarkers.push(marker);
      return marker;
    }
  });

  ready.then((upgradedIcon) => {
    if (!upgradedIcon) {
      return;
    }
    pendingMarkers.forEach((marker) => marker.setIcon(upgradedIcon));
  });

  return layer;
};

const initializeMap = async (datasets, settings) => {
	console.log('Initializing map with datasets:', datasets);
	console.log('Initializing map with settings:', settings);
	const bounds = calculateBounds(datasets);
	let lat = settings.default_lat ?? '52.1326'; // Default lat (Netherlands center)
	let long = settings.default_lng ?? '5.2913'; // Default long (Netherlands center)
// Default_zoom from the settings is only a fallback for when there are
// no markers (or all markers are in exactly the same place).
// As soon as there is a bounding box, calculateBounds automatically derives a
// suitable zoom and we overwrite it further with map.fitBounds().
// This ensures that the default_zoom setting is only used when there are no features to show, or when all features have the same coordinates (and thus no bounds can be calculated).
	let zoom = settings.default_zoom ?? 12;

	if ( !bounds ) {
		console.info("No valid bounds could be calculated from the datasets.");
		console.log("Center calculated as:", { lat, long, zoom });
	} else {
		const center = calculateCenter(bounds);
		lat = center.lat;
		long = center.long;
	}

	const config = {
		centerX: lat,
		centerY: long,
		minimumZoom: 4,
		maximumZoom: 18,
		defaultZoom: zoom,
		enableHomeControl: true,
		enableZoomControl: true,
		enableBoxZoomControl: true
	};

	const map = new L.Map(mapContainer.value, {
		center: [config.centerX, config.centerY],
		zoom: config.defaultZoom,
		minZoom: config.minimumZoom,
		maxZoom: config.maximumZoom,
		zoomControl: false,
		boxZoom: config.enableBoxZoomControl,
		defaultExtentControl: config.enableHomeControl,
	});

	map.setView([config.centerX, config.centerY], config.defaultZoom);

  if (config.enableZoomControl) {
    L.control.zoom({ position: 'bottomright' }).addTo(map);
  }

  // Add the tile layer *before* building the marker clusters so the base map is visible
  // immediately, even while individual marker SVGs are still being fetched in the background.
  // Previously this lived at the bottom of this function, which caused the whole map to
  // appear blank whenever an SVG fetch was slow.
  const tileLayerUri = new L.TileLayer(props.tileLayerUri);
  map.addLayer(tileLayerUri);

  const filteredDatasets = datasets.filter((dataset) => props.selectedDatasets.includes(dataset.id));

  const groupedMarkerClusters = await Promise.all(
    filteredDatasets.map(async (dataset) => {
      // Create a pane for this dataset.
      const pane = map.createPane(dataset.title.replace(' ', '_'));
      const cluster = L.markerClusterGroup({
        ...clusterOptions,
        clusterPane: pane
      });

			// Check if features is empty. If so, return early.
			if (!dataset.features || dataset.features.length === 0) {
				return {
					id: dataset.id,
					cluster,
          hasFeatures: false
				};
			}

			if (dataset.features.constructor !== Array) {
				dataset.features = [dataset.features];
			}

      for (const feature of dataset.features) {
        // createLayer is now synchronous: placeholders are applied immediately and each
        // marker upgrades itself when its SVG finishes fetching in the background.
        const layer = createLayer(feature, dataset);
        // Store feature and dataset data on the layer for later retrieval.
        layer._featureData = feature;
        layer._datasetData = dataset;
        // Also store on child layers if this is a layer group (like GeoJSON).
        if (layer.getLayers) {
          layer.eachLayer(childLayer => {
            childLayer._featureData = feature;
            childLayer._datasetData = dataset;
          });
        }
        attachEvents(layer, feature, dataset);
        cluster.addLayer(layer);
      }

			return {
				id: dataset.id,
				cluster,
        hasFeatures: true
			};
		})
  );

	L.Control.DataLayerFilters = L.Control.extend({
		options: {
			position: 'topleft',
		},
		onAdd: function () {
			const btn = L.DomUtil.create(
				'button',
				'leaflet-control-filters'
			);
			L.DomEvent.addListener(
				btn,
				'click',
				L.DomEvent.stopPropagation
			)
				.addListener(btn, 'click', L.DomEvent.preventDefault)
				.addListener(btn, 'click', function () {
					showFiltersCard.value = !showFiltersCard.value;
				});

			const title = 'Filter';
			btn.title = title;
			btn.innerHTML = makeFilterButtonHTML(
				'Filter',
				props.primaryColor
			);

			return btn;
		},
	});

	L.Control.ListViewToggle = L.Control.extend({
		options: {
			position: 'topleft',
		},
		onAdd: function () {
			const btn = L.DomUtil.create('button', 'leaflet-control-list-view');
			L.DomEvent.addListener(btn, 'click', L.DomEvent.stopPropagation)
				.addListener(btn, 'click', L.DomEvent.preventDefault)
				.addListener(btn, 'click', function () {
					emit('toggleView');
				});

			const title = 'Lijst';
			btn.title = title;
			btn.innerHTML = makeListViewButtonHTML(title, props.primaryColor);

			return btn;
		},
	});

	// Tile layer is already added near the top of initializeMap so the base map renders immediately.
	const datalayerFilters = new L.Control.DataLayerFilters();
	const listViewToggle = new L.Control.ListViewToggle();

  if (groupedMarkerClusters?.some(item => item.hasFeatures)) {
    map.addControl(listViewToggle);
  }

	if (groupedMarkerClusters?.length > 0) {
		map.addControl(datalayerFilters);
    showFiltersCard.value = true;
	}

  // Fit map view to marker bounds.
  if (bounds) {
    map.fitBounds([
      [bounds.minLat, bounds.minLong],
      [bounds.maxLat, bounds.maxLong],
    ], {
      padding: [40, 40],
      maxZoom: 15
    });

    // Calculate zoom based on bounds.
    zoom = map.getZoom();
    console.log('Center calculated as:', { lat, long, zoom });
  }

	groupedMarkerClusters.forEach(({ cluster }) => {
		map.addLayer(cluster);
    cluster.on('animationend layeradd spiderfied', () => {
      if (activeMarkerRef.value) {
        highlightSelectedMarker(activeMarkerRef.value, mapContainer.value);
      }
    });
	});
	clusters.value = groupedMarkerClusters;
	mapRef.value = map;

    if (window.openkaarten && typeof window.openkaarten.registerMap === 'function') {
		window.openkaarten.registerMap(map);
    }

	window.dispatchEvent(new CustomEvent('openkaarten:map-ready', {
		detail: { map }
	}));
};

const emit = defineEmits(['toggleView', 'datasetChange']);

onMounted(async () => {
	if (mapContainer.value) {
		await initializeMap(props.datasets, props.settings);
	}
});

// Add search handler
const handleSearch = async (query) => {
  searchQuery.value = query;
  const map = mapRef.value;

  if (!map || !query) return;

  try {
    const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}`
    );
    const results = await response.json();

    if (results.length > 0) {
      const { lat, lon } = results[0]; // Take the first (most relevant) match.
      const latLng = L.latLng(parseFloat(lat), parseFloat(lon));
      const targetIcon = L.icon({
        iconUrl: 'data:image/png;base64,',
        iconSize: [15, 24],
        iconAnchor: [0, 24],
        popupAnchor: [8, -7]
      });

      if (map && map._loaded) {
        map.once('zoomend', () => {
          if (lastSearchMarker.value) {
            map.removeLayer(lastSearchMarker.value);
          }
          const targetMarker = L.marker(latLng, { icon: targetIcon });
          targetMarker.addTo(map);
          targetMarker.bindPopup("Gevonden locatie");
          lastSearchMarker.value = targetMarker;
        });
        map.flyTo(latLng, 15, { animate: true, duration: 1 });
      }
      resultsCount.value = results.length ? 1 : 0
    }
  } catch (error) {
    console.error("Error in retrieving location:", error);
  }
};
</script>

<template v-cloak>
	<div
    :class="{
      'owc-openkaarten-streetmap__map': true,
      'filters-open': showFiltersCard,
      }"
	>
		<div class="owc-openkaarten-streetmap__controls">
			<BaseSearchInput
        :placeholder="'Zoek op straat en/of plaats of postcode'"
				:primary-color="primaryColor"
        :results-count="resultsCount"
				@search="handleSearch"
			/>
		</div>
		<div ref="mapContainer" class="owc-openkaarten-streetmap__map-canvas"></div>
    <Transition name="fade">
      <div
          v-if="showFiltersCard"
          class="owc-openkaarten-streetmap__overlay"
      ></div>
    </Transition>
		<Transition name="slide">
			<BaseFilters
				v-if="datasets && datasets.length > 0 && showFiltersCard"
				:open="showFiltersCard"
				:datasets="datasets.filter((set) => set.features?.length)"
				:selectedDatasets="selectedDatasets"
				:primaryColor="primaryColor"
				:mapElement="mapContainer"
				@closeFilters="closeFilters"
				@datasetChange="datasetChange"
			/>
		</Transition>
		<BaseTooltipCard
			v-if="tooltipCard"
			:key="tooltipCard.datasetId"
			:id="tooltipCard.datasetId"
			:tooltipArray="tooltipCard.tooltipArray"
			:properties="tooltipCard.properties"
			:primaryColor="primaryColor"
			@closeCard="closeTooltipCard"
		/>
	</div>
</template>

